// Material Ground (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_tint: vec4f,
  p_tiles: f32,
  p_extent: f32,
  p_shadeStrength: f32,
  p_glowStrength: f32,
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_grassMap: texture_2d<f32>;
@group(2) @binding(2) var tex_lightMap: texture_2d<f32>;
@group(2) @binding(3) var material_sampler: sampler;
const MATERIAL_MODEL: u32 = 0u;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec2f = (in.uv * material.p_tiles);
  let v1: vec4f = textureSample(tex_grassMap, material_sampler, v0);
  let v2: vec3f = v1.xyz;
  let v3: vec3f = material.p_tint.xyz;
  let v4: vec3f = (v2 * v3);
  let v5: vec3f = vec3f(1.0, 1.0, 1.0);
  let v6: vec3f = vec3f(0.5, 0.66, 0.86);
  let v7: vec2f = in.world_pos.xz;
  let v8: vec2f = (v7 / material.p_extent);
  let v9: vec2f = (v8 + 0.5);
  let v10: vec2f = vec2f(0.0);
  let v11: vec2f = vec2f(1.0);
  let v12: vec2f = clamp(v9, v10, v11);
  let v13: vec4f = textureSample(tex_lightMap, material_sampler, v12);
  let v14: f32 = v13.x;
  let v15: f32 = (v14 * material.p_shadeStrength);
  let v16: f32 = (v15 * 2.2);
  let v17: vec3f = vec3f(v16);
  let v18: vec3f = mix(v5, v6, v17);
  let v19: vec3f = (v4 * v18);
  let v20: vec3f = vec3f(1.0, 0.82, 0.45);
  let v21: vec3f = (v20 * v4);
  let v22: f32 = v13.y;
  let v23: f32 = (v22 * material.p_glowStrength);
  let v24: f32 = (v23 * 2.4);
  let v25: vec3f = (v21 * v24);
  let v26: vec3f = (v19 + v25);
  out.base_color = v26;
  out.roughness = 0.95;
  return out;
}
